31.1', '/home/primeline/Data/IRnotator/work/c6/c8e6a28eb1ba488ca7635f6eceecf3/XP_059098031.1', 'XP_059097759.1', '/home/primeline/Data/IRnotator/work/93/6004ed347540b31f2e6b3693de3d26/XP_059097759.1', 'XP_059096791.1', '/home/primeline/Data/IRnotator/work/a5/4f62549eab32335b70ec1ed6af1447/XP_059096791.1', 'XP_059097426.1', '/home/primeline/Data/IRnotator/work/34/43816bbf3130a0190475f55cf06f70/XP_059097426.1', 'XP_059097354.1', '/home/primeline/Data/IRnotator/work/f9/ebf69be9e93d44f362f53208209fe0/XP_059097354.1', 'XP_059097643.1', '/home/primeline/Data/IRnotator/work/2d/ef8ecdf09f898feee4be5aa5f892ba/XP_059097643.1', 'XP_059097263.1', '/home/primeline/Data/IRnotator/work/29/30b77ece6c4827d057ce4f113d6450/XP_059097263.1', 'XP_059097644.1', '/home/primeline/Data/IRnotator/work/3e/2706e4070d723483b30cb941c79254/XP_059097644.1', 'XP_059097430.1', '/home/primeline/Data/IRnotator/work/79/cc0f72f246b1e5fac465c78871172f/XP_059097430.1']

    # Collected list of (seq_id, path) tuples flattens to [id, path, id, path, ...]
    paths = []
    i = 0
    while i < len(raw):
        p = Path(str(raw[i]))
        if p.exists() and p.is_dir():
            paths.append(p)
            i += 1
            continue
        if i + 1 < len(raw):
            p2 = Path(str(raw[i + 1]))
            if not p2.exists():
                raise FileNotFoundError(f"DeepTMHMM result path does not exist: {p2}")
            paths.append(p2)
            i += 2
            continue
        raise ValueError(f"Unpaired item in deeptmhmm_results collect: {raw[i]!r}")

    if not paths:
        raise RuntimeError("No DeepTMHMM result directories to merge")

    out = Path("deeptmhmm_summary/TMRs.gff3")
    wrote_gff_version = False
    with out.open("w") as w:
        for idx, d in enumerate(paths):
            gff = d / "TMRs.gff3"
            if not gff.is_file():
                raise FileNotFoundError(f"missing TMRs.gff3 in {d}")

            # Batch-mode DeepTMHMM separates sequence blocks with //
            if idx > 0:
                w.write("//
")

            with gff.open() as fh:
                for line in fh:
                    if line.startswith("##gff-version"):
                        if not wrote_gff_version:
                            w.write(line)
                            wrote_gff_version = True
                        continue
                    # Keep per-sequence # headers, feature lines, and any // already present
                    w.write(line)
    PY
